const row = $json;
const keys = Object.keys(row);
const abertas = keys.slice(-4);
const id = String(row['Timestamp'] || $itemIndex).replace(/[^0-9A-Za-z]/g, '');
const texto = abertas.map((k, i) => {
  const t = String(row[k] ?? '').replace(/[<>]/g, '').trim();
  return `<resposta id="R${id}-P${i + 1}" pergunta="${i + 1}">${t}</resposta>`;
}).join('\n');
return { json: { respondente: id, lote: `<respostas>\n${texto}\n</respostas>` } };

const saida = [];
const juntar = (v) => Array.isArray(v) ? v.join(', ') : (v ?? '');

for (const item of $input.all()) {
  const bruto = String(item.json.text ?? item.json.output ?? '');
  const limpo = bruto.replace(/```json|```/g, '').trim();
  let lista;
  try {
    lista = JSON.parse(limpo);
    if (!Array.isArray(lista)) lista = [lista];
  } catch (e) {
    saida.push({ json: { id: 'ERRO', respondente: '', pergunta: '', resumo: 'Falha ao ler o JSON da IA' } });
    continue;
  }
  for (const r of lista) {
    const id = String(r.id ?? '');
    saida.push({ json: {
      id,
      respondente: id.split('-P')[0],
      pergunta: id.includes('-P') ? id.split('-P')[1] : '',
      valida: r.valida ?? '',
      sentimento: r.sentimento ?? '',
      temas: juntar(r.temas),
      tensao_wellness: r.tensao_wellness ?? '',
      minimiza_risco: r.minimiza_risco ?? '',
      fator_prejudicial: juntar(r.fator_prejudicial),
      tipo_acao: juntar(r.tipo_acao),
      especificidade: r.especificidade ?? '',
      posicao_saudavel: r.posicao_saudavel ?? '',
      resumo: r.resumo ?? ''
    }});
  }
}
return saida;
